const loadImage = (url) => new Promise((resolve, reject) => {
    const img = new Image();
    if (/^https?:/.test(url))
        img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('Failed to load ' + url));
    img.src = url;
});
const luma = (d, i) => 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
const makeCanvas = (w, h) => {
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.ceil(w));
    c.height = Math.max(1, Math.ceil(h));
    return c;
};
function keyRing(img, size, minHoleFrac) {
    const c = makeCanvas(size, size);
    const ctx = c.getContext('2d');
    const sc = Math.max(size / img.width, size / img.height);
    const dw = img.width * sc;
    const dh = img.height * sc;
    ctx.drawImage(img, (size - dw) / 2, (size - dh) / 2, dw, dh);
    const id = ctx.getImageData(0, 0, size, size);
    const d = id.data;
    const cx = size / 2;
    const cy = size / 2;
    const nb = Math.ceil(size / 2) + 2;
    const sum = new Float32Array(nb);
    const cnt = new Float32Array(nb);
    const rad = new Float32Array(size * size);
    for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
            const p = y * size + x;
            const r = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
            rad[p] = r;
            const b = Math.min(nb - 1, Math.round(r));
            sum[b] += luma(d, p * 4);
            cnt[b]++;
        }
    }
    const prof = (b) => (cnt[b] ? sum[b] / cnt[b] : 0);
    let rOuter = size / 2;
    for (let b = Math.floor(size / 2) - 1; b > 0; b--) {
        if (prof(b) > 10) {
            rOuter = Math.min(size / 2, b + 2);
            break;
        }
    }
    let rInner = 0;
    for (let b = 0; b < rOuter; b++) {
        if (prof(b) > 10) {
            rInner = Math.max(0, b - 2);
            break;
        }
    }
    rInner = Math.max(rInner, rOuter * minHoleFrac);
    for (let p = 0; p < size * size; p++) {
        const r = rad[p];
        const i = p * 4;
        let a = smoothstep(rInner - 2, rInner + 2, r) * (1 - smoothstep(rOuter - 2, rOuter + 2, r));
        a *= smoothstep(5, 15, luma(d, i));
        d[i + 3] = Math.round(a * 255);
    }
    ctx.putImageData(id, 0, 0);
    const os = Math.ceil(rOuter * 2);
    const out = makeCanvas(os, os);
    out.getContext('2d').drawImage(c, cx - rOuter, cy - rOuter, os, os, 0, 0, os, os);
    return out;
}
function keyRail(img) {
    const w = Math.min(img.width, 2048);
    const h = Math.round(img.height * (w / img.width));
    const c = makeCanvas(w, h);
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, w, h);
    const id = ctx.getImageData(0, 0, w, h);
    const d = id.data;
    const rows = new Float32Array(h);
    for (let y = 0; y < h; y++) {
        let lit = 0;
        for (let x = 0; x < w; x++) {
            const i = (y * w + x) * 4;
            const l = luma(d, i);
            if (l > 22)
                lit++;
            d[i + 3] = Math.round(smoothstep(6, 18, l) * 255);
        }
        rows[y] = lit / w;
    }
    let y0 = 0;
    let y1 = h - 1;
    for (let y = 0; y < h; y++)
        if (rows[y] > 0.03) {
            y0 = Math.max(0, y - 3);
            break;
        }
    for (let y = h - 1; y >= 0; y--)
        if (rows[y] > 0.03) {
            y1 = Math.min(h - 1, y + 3);
            break;
        }
    if (y1 - y0 < h * 0.08) {
        y0 = Math.floor(h * 0.3);
        y1 = Math.floor(h * 0.7);
    }
    ctx.putImageData(id, 0, 0);
    const out = makeCanvas(w, y1 - y0 + 1);
    out.getContext('2d').drawImage(c, 0, y0, w, y1 - y0 + 1, 0, 0, w, y1 - y0 + 1);
    return out;
}
function softSprite(img, size, rgb, gamma = 1.1) {
    const c = makeCanvas(size, size);
    const ctx = c.getContext('2d');
    const sc = Math.min(size / img.width, size / img.height);
    const dw = img.width * sc;
    const dh = img.height * sc;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, size, size);
    ctx.drawImage(img, (size - dw) / 2, (size - dh) / 2, dw, dh);
    const id = ctx.getImageData(0, 0, size, size);
    const d = id.data;
    const cx = size / 2;
    for (let p = 0; p < size * size; p++) {
        const i = p * 4;
        const x = p % size;
        const y = (p - x) / size;
        const edge = 1 - smoothstep(size * 0.36, size * 0.5, Math.hypot(x - cx, y - cx));
        const a = Math.pow(luma(d, i) / 255, gamma) * edge;
        d[i] = rgb[0];
        d[i + 1] = rgb[1];
        d[i + 2] = rgb[2];
        d[i + 3] = Math.round(a * 255);
    }
    ctx.putImageData(id, 0, 0);
    return c;
}
function keyLogo(img) {
    const w = Math.min(img.width, 1400);
    const h = Math.round(img.height * (w / img.width));
    const c = makeCanvas(w, h);
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, w, h);
    const id = ctx.getImageData(0, 0, w, h);
    const d = id.data;
    let minX = w, minY = h, maxX = 0, maxY = 0;
    for (let p = 0; p < w * h; p++) {
        const i = p * 4;
        const a = smoothstep(12, 48, luma(d, i));
        d[i + 3] = Math.round(a * 255);
        if (a > 0.3) {
            const x = p % w;
            const y = (p - x) / w;
            if (x < minX)
                minX = x;
            if (x > maxX)
                maxX = x;
            if (y < minY)
                minY = y;
            if (y > maxY)
                maxY = y;
        }
    }
    ctx.putImageData(id, 0, 0);
    if (maxX <= minX || maxY <= minY)
        return c;
    const pad = Math.round(w * 0.02);
    minX = Math.max(0, minX - pad);
    minY = Math.max(0, minY - pad);
    maxX = Math.min(w - 1, maxX + pad);
    maxY = Math.min(h - 1, maxY + pad);
    const out = makeCanvas(maxX - minX + 1, maxY - minY + 1);
    out.getContext('2d').drawImage(c, minX, minY, out.width, out.height, 0, 0, out.width, out.height);
    return out;
}
function makeGrain() {
    const s = 192;
    const c = makeCanvas(s, s);
    const ctx = c.getContext('2d');
    const id = ctx.createImageData(s, s);
    for (let i = 0; i < s * s * 4; i += 4) {
        const v = 110 + Math.random() * 90;
        id.data[i] = v;
        id.data[i + 1] = v;
        id.data[i + 2] = v;
        id.data[i + 3] = 255;
    }
    ctx.putImageData(id, 0, 0);
    return c;
}
async function loadAssets() {
    const [plate, ringA, ringB, core, rail, smoke] = await Promise.all([plateUrl, ringAUrl, ringBUrl, coreUrl, railUrl, smokeUrl].map(loadImage));
    const logo = await loadImage(logoUrl);
    const logoKeyed = keyLogo(logo);
    return {
        plate,
        core,
        ringA: keyRing(ringA, 1024, 0.5),
        ringB: keyRing(ringB, 1024, 0.62),
        rail: keyRail(rail),
        smokeGray: softSprite(smoke, 384, [150, 146, 142]),
        smokeWarm: softSprite(smoke, 384, [255, 150, 70], 1.3),
        logo: logoKeyed,
        logoUrl: logoKeyed.toDataURL('image/png'),
        grain: makeGrain(),
    };
}
function computeGeo(w, h) {
    const portrait = h > w;
    const R = Math.min(w, h) * 0.5 * (portrait ? 1.35 : 1);
    const halfDiag = Math.hypot(w, h) / 2;
    const rIn = 0.38 * R;
    const rOut = halfDiag * 1.1 + R * 0.1;
    const bladeW = 0.12 * R;
    const irisPivotR = 0.44 * R;
    return {
        w, h, cx: w / 2, cy: h / 2, R, halfDiag,
        rIn, rOut, plateD: halfDiag + 0.12 * R,
        bearingR0: 0.36 * R, bearingR1: 0.64 * R,
        railW: 0.1 * R, railHead: 0.5 * R, headLen: 0.14 * R, headW: 0.2 * R, prong: 0.05 * R,
        railBodyX0: 0.74 * R, railLen: halfDiag * 1.25 - 0.74 * R + R * 0.3, railD: halfDiag * 1.2,
        irisPivotR, bladeL: 0.45 * R, bladeW,
        irisOpen: Math.PI / 2,
        irisClosed: Math.asin(clamp((0.25 * R + bladeW / 2) / irisPivotR, 0.2, 0.95)),
        coreR: 0.13 * R,
        tunnel: [
            { r: 0.52 * R, z: 0.5, omega: 0.14, tex: 'A' },
            { r: 0.37 * R, z: 0.38, omega: -0.3, tex: 'B' },
            { r: 0.27 * R, z: 0.27, omega: 0.55, tex: 'B' },
            { r: 0.19 * R, z: 0.17, omega: -0.9, tex: 'A' },
        ],
    };
}
