        const g = this.ctx.createLinearGradient(0, -rw / 2, 0, rw / 2);
        g.addColorStop(0, '#3b3d42');
        g.addColorStop(0.25, '#a7a9ae');
        g.addColorStop(0.55, '#6c6e73');
        g.addColorStop(1, '#202226');
