        P.irisRetract = 0;
        P.coreI = 0.88 + 0.35 * this.coreBump + 0.06 * noise1(now * 9, 1);
        P.coreScale = 1;
        P.glowR = 0.32 * R;
        P.glowA = 0.3 + 0.2 * this.coreBump;
        P.pulseR = this.pulsePhase * 1.35 * R;
        P.pulseA = 0.4 * Math.pow(1 - this.pulsePhase, 2);
